  A.ppick = function (id) { var s = S(), a = T.cur.arg, p = s[a.k]; if (!id) { if (a.k == 'party' && p.filter(Boolean).length <= 1) { T.toast('1파티에는 최소 한 명이 필요합니다'); return; } p.splice(a.i, 1); } else { ['party', 'partyB'].forEach(function (k) { var j = s[k].indexOf(id); if (j >= 0) { if (k == 'party' && s.party.length <= 1 && a.k != 'party') return; s[k].splice(j, 1); } }); if (s.party.length == 0) { s.party.push(id); } else if (p.indexOf(id) < 0) { if (a.i < p.length) p[a.i] = id; else p.push(id); } s.exped = s.exped.filter(function (e) { return e.c != id; }); } s.active = 0; a.k = null; ST.ver++; T.dirty = true; T.refresh(); };

