  A.quickfood = function () { var s = S(), c = s.chars[G.cur()]; if (G.mode != 'play') return; var dead = s.party.some(function (x) { return s.chars[x].hp <= 0; }); var list = Object.keys(s.inv).filter(function (k) { var it = D.ITEMS[k]; return it && it.cat == 'food' && ((it.heal && !it.buff && c.hp > 0 && c.hp < 1) || (it.revive && dead && c.hp > .6)); }).sort(function (a, b) { return (D.ITEMS[b].heal ? D.ITEMS[b].heal[0] : 0) - (D.ITEMS[a].heal ? D.ITEMS[a].heal[0] : 0); }); if (!list.length) { T.toast(c.hp >= 1 ? 'HP가 가득합니다' : '먹을 수 있는 회복 음식이 없습니다'); return; } err(eat(list[0])); };

