  SC.shop = function (k) { k = k || 'general'; var sh = D.SHOP[k]; return win(sh.n, '<div class="body"><div class="col" style="flex:1"><div class="grid">' + sh.items.map(function (it, i) { var left = ST.shopLeft(k, i); return '<div class="card" style="width:380px;margin:0"><div class="row">' + T.ic(it[0]) + '<b>' + T.name(it[0]) + '</b></div><div class="xs dim">' + (D.ITEMS[it[0]].d || '') + '</div><div class="row sm">' + T.ic(sh.cur) + U.fmt(it[1]) + '<span class="dim">남은 수량 ' + left + '</span><div class="sp"></div><button data-a="buy:' + k + ':' + i + '"' + (left > 0 && ST.cnt(sh.cur) >= it[1] ? '' : ' disabled') + '>구매</button></div></div>'; }).join('') + '</div></div></div>', 'mid'); };
  function craftList(list, act) { return list.map(function (r, i) { var c = Object.assign({}, r.need); if (r.coin) c.coin = r.coin; return '<div class="card"><div class="row">' + T.ic(r.out) + '<h3>' + T.name(r.out) + (r.n > 1 ? ' ×' + r.n : '') + '</h3><div class="sp"></div><button class="gold" data-a="' + act + ':' + i + ':1"' + (ST.can(c) ? '' : ' disabled') + '>제작</button>' + (r.weapon ? '' : '<button data-a="' + act + ':' + i + ':10"' + (ST.can(c) ? '' : ' disabled') + '>×10</button>') + '</div><div class="sm">' + cost(c) + '</div></div>'; }).join(''); }
  SC.forge = function () { return win('대장간 — 무기 제작 · 광석 정제', '<div class="body"><div class="col" style="flex:1"><div class="card sm">철광석과 수정 원석은 바위 지대에서 무기로 캐낼 수 있습니다. 4성 무기 다섯 종은 이곳에서만 만들 수 있습니다.</div>' + craftList(D.FORGE, 'craftF') + '</div></div>', 'mid'); };
  SC.alchemy = function () { return win('합성대', '<div class="body"><div class="col" style="flex:1"><div class="card sm">낮은 등급 재료 세 개를 높은 등급 하나로 합성합니다.</div>' + craftList(D.ALCHEMY, 'craftA') + '</div></div>', 'mid'); };
  function craft(list, i, n) { var r = list[+i], c = Object.assign({}, r.need), made = 0; if (r.coin) c.coin = r.coin; for (var k = 0; k < +n; k++) { if (!ST.take(c)) break; ST.add(r.out, r.n); made++; } if (made) { AUD.sfx('mine'); T.loot(r.out, r.n * made); G.qCheck && 0; } T.refresh(); }
  A.craftF = function (i, n) { craft(D.FORGE, i, n); }; A.craftA = function (i, n) { craft(D.ALCHEMY, i, n); };
  var ck = null;
  SC.cook = function (a) {
    if (ck && ck.run) return win('요리 — ' + T.name(ck.id), '<div class="body"><div class="col" style="flex:1;text-align:center"><div style="font-size:34px;margin-top:60px">바늘이 <span class="gold">노란 칸</span>에 왔을 때 멈추세요!</div><div class="fishbar"><div class="zone" style="left:30%;width:40%;background:#4a8a5a"></div><div class="zone" style="left:43%;width:14%;background:#ffd060"></div><div class="nd" id="cknd" style="left:0"></div></div><button class="gold" style="font-size:40px;padding:16px 80px" data-a="cookstop">멈추기!</button></div></div>', 'mid');
    return win('요리', '<div class="body"><div class="col" style="flex:1"><div class="card sm">재료를 넣고 불 조절 미니게임에 성공하면 요리가 완성됩니다. 완벽하게 익히면 한 접시 더!</div>' + D.RECIPES.map(function (r) { var it = D.ITEMS[r.id]; return '<div class="card"><div class="row">' + T.ic(r.id) + '<h3>' + it.n + '</h3><span class="sm dim">' + it.d + '</span><div class="sp"></div><span class="dim sm">보유 ' + ST.cnt(r.id) + '</span><button class="gold" data-a="cook:' + r.id + '"' + (ST.can(r.need) ? '' : ' disabled') + '>조리</button></div><div class="sm">' + cost(r.need) + '</div></div>'; }).join('') + '</div></div>', 'mid');
  };
  A.cook = function (id) { var r = D.RECIPES.filter(function (x) { return x.id == id; })[0]; if (!ST.take(r.need)) return; ck = { id: id, run: true, p: 0, d: 1 }; AUD.sfx('cook'); T.refresh(); clearInterval(ck.iv); ck.iv = setInterval(function () { if (!ck || !ck.run || !T.cur || T.cur.name != 'cook') { clearInterval(ck && ck.iv); if (ck && ck.run) { ck.run = false; ST.add(ck.id, 1); } return; } ck.p += ck.d * .028; if (ck.p > 1) { ck.p = 1; ck.d = -1; } if (ck.p < 0) { ck.p = 0; ck.d = 1; } var e = document.getElementById('cknd'); if (e) e.style.left = (ck.p * 100) + '%'; if (T.autoDlg && Math.abs(ck.p - .5) < .05) A.cookstop(); }, 30); };
  A.cookstop = function () { if (!ck || !ck.run) return; ck.run = false; clearInterval(ck.iv); var d = Math.abs(ck.p - .5), n = d < .07 ? 2 : 1, msg = d < .07 ? '완벽한 요리! (2접시)' : d < .2 ? '맛있게 완성!' : '조금 탔지만… 먹을 만합니다'; ST.add(ck.id, n); T.loot(ck.id, n); T.toast(msg); AUD.sfx(d < .2 ? 'solve' : 'deny'); ST.bump('cooks', 1); T.refresh(); };

  // ═════ 석상·비경·첨탑 ═════
  SC.statue = function (r) {
    var s = S(), ri = ['meadow', 'canyon', 'snow'].indexOf(r.reg), got = W.o.orbs.filter(function (o) { return o.reg == ri && s.orbs[o.id]; }).length, have = got - s.offered[ri], lv = s.offered[ri] / 4;
    return win('길잡이 석상 — ' + D.REGION[r.reg].n, '<div class="body"><div class="col" style="flex:1"><div class="card"><h3 class="ok">파티 전원 회복 완료</h3><div class="sm">석상에 손을 대면 파티 전원이 회복되고 쓰러진 동료가 일어납니다.</div></div><div class="card"><h3>' + D.REGION[r.reg].orb + ' 봉헌 (단계 ' + lv + ' / 2)</h3><div class="sm">이 지역에서 모은 구슬: <span class="gold">' + got + ' / 8</span> · 바칠 수 있는 구슬: <span class="gold">' + have + '</span><br>4개를 바칠 때마다 <span class="gold">최대 스태미나 +10</span>, 별조각 60, 길잡이 별등 1개를 받습니다. (현재 최대 스태미나 ' + s.stam + ')</div><div class="row"><button class="gold" data-a="offer:' + ri + '"' + (have >= 4 && lv < 2 ? '' : ' disabled') + '>구슬 4개 바치기</button></div></div></div></div>', 'small');
  };
  A.offer = function (ri) { var s = S(); ri = +ri; s.offered[ri] += 4; s.stam += 10; AUD.sfx('clear'); G.giveRewards({ gem: 60, tk_s: 1, arxp: 200 }); T.toast('최대 스태미나가 ' + s.stam + '(으)로 늘어났습니다!'); T.refresh(); };
  SC.gate = function (g) {
    var s = S(), wl = ST.WL(), body;
    if (g.kind == 'tower') { body = '<div class="card sm">층마다 조건이 다릅니다. 전반전은 1파티, 후반전은 2파티로 싸우며 제한 시간 ' + D.TOWER_TIME + '초 안에 양쪽을 모두 끝내야 합니다. 남은 시간 ' + D.TOWER_STAR[1] + '초 이상 ★★, ' + D.TOWER_STAR[2] + '초 이상 ★★★. 별 하나당 첫 보상 별조각 50.</div>' + D.TOWER.map(function (f, i) { var open = i == 0 || (s.tower[i - 1] || 0) > 0; return '<div class="card"><div class="row"><h3>' + f.n + '</h3><span class="stars">' + '★★★'.slice(0, s.tower[i] || 0) + '</span><div class="sp"></div><span class="dim sm">적 레벨 ' + f.lvl + '</span><button class="gold" data-a="tower:' + i + '"' + (open ? '' : ' disabled') + '>' + (open ? '도전' : '이전 층 필요') + '</button></div><div class="sm">조건: <span class="gold">' + f.cond + '</span></div></div>'; }).join('') + '<div class="row"><button data-a="open:party">파티 편성 (1·2파티)</button></div>'; }
    else if (g.kind == 'weekly') { var done = s.weekly == U.weekKey(); body = '<div class="card"><h3>폭풍의 비룡 템페스타</h3><div class="sm">주간 보스. 체력에 따라 세 단계로 변합니다. 약점: 얼음 · 바위<br>권장 레벨 ' + (g.lvl + wl * 6) + ' · 보상 수령에 여명의 이슬 60 필요 (주 1회' + (done ? ' — <span class="bad">이번 주 수령 완료</span>' : '') + ')<br>보상: 폭풍의 비늘(높은 특성 레벨 재료), 5성 장신구, 별조각 60</div><div class="row"><button class="gold" data-a="domain">도전</button></div></div>'; }
    else { var drops = g.kind == 'art' ? g.sets.map(function (k) { return '<b style="color:' + D.SETS[k].col + '">' + D.SETS[k].n + '</b> (2: ' + D.SETS[k].d2 + ' / 4: ' + D.SETS[k].d4 + ')'; }).join('<br>') : '오늘(' + D.DAYNAME[U.weekday()] + '요일) 드롭: ' + D.DAYSET().map(function (x) { return T.ic((g.kind == 'tal' ? 'tb_' : 'wm_') + x + '1') + T.name((g.kind == 'tal' ? 'tb_' : 'wm_') + x + '1'); }).join(', ') + '<br><span class="dim xs">월·목 / 화·금 / 수·토에 종류가 바뀌고 일요일은 전부 나옵니다</span>'; body = '<div class="card"><h3>' + g.name + '</h3><div class="sm">' + { art: '장신구 비경', tal: '특성 재료 비경', wpn: '무기 돌파 재료 비경' }[g.kind] + ' · 권장 레벨 ' + (g.lvl + wl * 6) + ' · 적 2웨이브<br>클리어 후 보상 수령에 <span class="gold">여명의 이슬 20</span> 필요 (현재 ' + ST.dew() + ')<br><br>' + drops + '</div><div class="row"><button class="gold" data-a="domain">도전</button></div></div>'; }
    return win(g.name, '<div class="body"><div class="col" style="flex:1">' + body + '</div></div>', 'mid');
  };
  A.domain = function () { var g = T.cur.arg; T.close(); G.startDomain(g); }; A.tower = function (i) { T.close(); G.startTower(+i); };
  SC.domainResult = function (g) { var cst = g.kind == 'weekly' ? 60 : 20; return win('비경 클리어!', '<div class="body"><div class="col" style="flex:1;text-align:center"><div style="font-size:60px;color:#ffe9a0;margin:30px">' + g.name + '</div><div>보상을 받으려면 여명의 이슬 ' + cst + '이(가) 필요합니다 (현재 ' + ST.dew() + ')</div><div class="row" style="justify-content:center;margin-top:30px"><button class="gold" style="font-size:32px" data-a="dreward">보상 수령 (이슬 ' + cst + ')</button><button style="font-size:32px" data-a="dleave">나가기</button></div></div></div>', 'small'); };
  A.dreward = function () { var e = G.domainRewards(T.cur.arg); if (e) { T.toast(e); return; } T.close(); setTimeout(function () { G.exitInst(); }, 900); }; A.dleave = function () { T.close(); G.exitInst(); };
  SC.towerResult = function (r) { var f = D.TOWER[r.fi]; return win(f.n, '<div class="body"><div class="col" style="flex:1;text-align:center"><div style="font-size:70px;margin:20px" class="' + (r.ok ? 'gold' : 'bad') + '">' + (r.ok ? '도전 성공' : '도전 실패') + '</div><div style="font-size:110px" class="stars">' + '★★★'.slice(0, r.stars) + '<span class="dim">' + '☆☆☆'.slice(0, 3 - r.stars) + '</span></div><div>남은 시간 ' + Math.max(0, r.left).toFixed(1) + '초' + (r.gain ? ' · 첫 달성 보상 ' + T.ic('gem') + '×' + r.gain : '') + '</div><div class="row" style="justify-content:center;margin-top:30px"><button class="gold" style="font-size:32px" data-a="dleave">확인</button></div></div></div>', 'small'); };

  // ═════ 낚시 ═════
  var fs2 = null;
  SC.fishing = function () {
    if (!fs2 || fs2.end) { fs2 = { ph: 'wait', t: 1.2 + Math.random() * 2.5, p: .5, v: 0, prog: .35, z: .5, hold: false, k: 0 }; clearInterval(T._fi); T._fi = setInterval(fishTick, 33); }
    return win('낚시', '<div class="body"><div class="col" style="flex:1;text-align:center"><div id="fmsg" style="font-size:40px;margin-top:40px;min-height:60px">찌를 지켜보세요…</div><div class="fishbar"><div class="zone" id="fzone" style="left:40%;width:20%"></div><div class="nd" id="fnd" style="left:50%"></div></div><div class="bar" style="width:800px;margin:20px auto"><i id="fprog" style="width:35%;background:#6cf"></i></div><button class="gold" id="fbtn" style="font-size:40px;padding:20px 100px;margin-top:20px">채기 / 당기기 (꾹 누르기)</button><div class="dim sm" style="margin-top:20px">「!」가 뜨면 버튼을 누르고, 흰 눈금을 초록 칸 안에 유지하세요. 누르면 오른쪽, 떼면 왼쪽으로 움직입니다. (스페이스·F 키도 가능)</div></div></div>', 'mid');
  };
  T.fishKey = function (down) { if (fs2 && !fs2.end) fishBtn(down); };
  function fishBtn(down) { if (!fs2) return; fs2.hold = down; if (down && fs2.ph == 'bite') { fs2.ph = 'reel'; AUD.sfx('splash'); } else if (down && fs2.ph == 'wait') { fs2.t = Math.max(fs2.t, .8); } }
  function fishTick() {
    if (!T.cur || T.cur.name != 'fishing' || !fs2) { clearInterval(T._fi); fs2 = null; return; } var m = document.getElementById('fmsg'), b = document.getElementById('fbtn'); if (!m) return;
    if (!b.bound) { b.bound = 1; var dn = function (e) { e.preventDefault(); fishBtn(true); }, up = function () { fishBtn(false); }; b.addEventListener('mousedown', dn); b.addEventListener('touchstart', dn, { passive: false }); window.addEventListener('mouseup', up); window.addEventListener('touchend', up); }
    var dt = .033; fs2.k += dt;
    if (fs2.ph == 'wait') { fs2.t -= dt; m.textContent = '찌를 지켜보세요…'; if (fs2.t <= 0) { fs2.ph = 'bite'; fs2.t = 1.3; AUD.sfx('fish'); } }
    else if (fs2.ph == 'bite') { fs2.t -= dt; m.innerHTML = '<span class="gold" style="font-size:70px">!</span> 지금 채세요!'; if (T.autoDlg) fishBtn(true); if (fs2.t <= 0) fin(false, '물고기가 달아났습니다…'); }
    else if (fs2.ph == 'reel') { m.textContent = '초록 칸에 맞춰 버티세요!'; fs2.z = .5 + Math.sin(fs2.k * 1.3) * .28 + Math.sin(fs2.k * 3.1) * .08; if (T.autoDlg) fs2.hold = fs2.p < fs2.z; fs2.v += (fs2.hold ? 2.4 : -2.4) * dt; fs2.v *= .93; fs2.p = U.clamp(fs2.p + fs2.v * dt * 1.6, 0, 1); if (fs2.p <= 0 || fs2.p >= 1) fs2.v = 0; var inz = Math.abs(fs2.p - fs2.z) < .11; fs2.prog += (inz ? .3 : -.28) * dt; document.getElementById('fzone').style.left = ((fs2.z - .11) * 100) + '%'; document.getElementById('fzone').style.width = '22%'; document.getElementById('fnd').style.left = (fs2.p * 100) + '%'; document.getElementById('fprog').style.width = (U.clamp(fs2.prog, 0, 1) * 100) + '%'; if (fs2.prog >= 1) fin(true); else if (fs2.prog <= 0) fin(false, '줄이 끊어졌습니다…'); }
    function fin(ok, msg) { fs2.end = true; clearInterval(T._fi); if (ok) { var gold = Math.random() < .12, id = gold ? 'gfish' : 'fish'; G.loot(id, 1); ST.bump('fishes', 1); AUD.sfx('chest'); T.toast(T.name(id) + '을(를) 낚았습니다!'); G.qCheck(); } else { T.toast(msg); AUD.sfx('deny'); } fs2 = null; T.close(); }
  }

  // ═════ 메뉴(설정·저장) ═════
  SC.menu = function (a) {
    var s = S(), exp = a == 'export' ? '<textarea readonly id="savetxt">' + ST.exportS() + '</textarea><div class="row"><button data-a="savedl">파일로 내려받기</button><button data-a="savecopy">복사</button></div>' : '', imp = a == 'import' ? '<textarea id="loadtxt" placeholder="내보낸 저장 문자열을 붙여 넣으세요"></textarea><div class="row"><button class="gold" data-a="saveload">불러오기</button><input type="file" id="loadfile" accept=".txt" style="font-size:20px"></div>' : '';
    return win('메뉴', '<div class="body"><div class="col" style="flex:1"><div class="card"><h3>소리</h3><div class="row">음악 <input type="range" min="0" max="100" value="' + Math.round(s.set.bgm * 100) + '" oninput="UI.setVol(\'bgm\',this.value)"> 효과음 <input type="range" min="0" max="100" value="' + Math.round(s.set.sfx * 100) + '" oninput="UI.setVol(\'sfx\',this.value)"></div></div>' +
      '<div class="card"><h3>저장</h3><div class="sm dim">진행 상황과 기원 기록은 이 브라우저(localStorage)에 자동 저장됩니다.</div><div class="row"><button data-a="tab:export">저장 내보내기</button><button data-a="tab:import">저장 불러오기</button><button data-a="savenow">지금 저장</button></div>' + exp + imp + '</div>' +
      '<div class="card"><h3>기타</h3><div class="row"><button data-a="photo">사진 모드</button><button data-a="unstuck">끼임 탈출 (마을로)</button><button data-a="totitle">시작 화면으로</button></div></div>' +
      '<div class="card"><h3>조작법</h3><div class="sm">이동 WASD · 카메라 마우스(화면 클릭 후) / 드래그 · 휠 줌 · 공격 마우스 왼쪽(꾹 누르면 강공격, 공중에서 낙하 공격)<br>점프·활공·벽 뛰어오르기 Space · 대시/달리기 Shift · 벽에서 내려오기 X · 스킬 E · 필살기 Q · 교체 1~4<br>상호작용 F · 정령안 V · 음식 Z · 지도 M · 가방 B · 캐릭터 C · 임무 J · 기원 G · 파티 L · 모험 수첩 K · 메뉴 Esc<br>휴대폰: 왼쪽 화면 스틱 · 오른쪽 화면 끌어서 카메라 · 버튼 · 초상화 눌러 교체<br>벽을 향해 계속 밀면 벽을 탑니다. 공중에서 점프를 누르면 활공합니다.</div></div></div></div>', 'mid');
  };
  T.setVol = function (k, v) { var s = S(); s.set[k] = v / 100; AUD.setVol(s.set.bgm, s.set.sfx); };
  A.savenow = function () { G.savePos(); ST.save(); T.toast('저장했습니다'); };
  A.savedl = function () { var a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([ST.exportS()], { type: 'text/plain' })); a.download = 'dotria_save.txt'; a.click(); };
  A.savecopy = function () { var t = document.getElementById('savetxt'); t.select(); try { document.execCommand('copy'); T.toast('복사했습니다'); } catch (e) { } };
  A.saveload = function () { var f = document.getElementById('loadfile'), t = document.getElementById('loadtxt'); function go(txt) { try { ST.importS(txt); location.reload(); } catch (e) { T.toast('저장 데이터를 읽을 수 없습니다'); } } if (f && f.files[0]) { var r = new FileReader(); r.onload = function () { go(r.result); }; r.readAsText(f.files[0]); } else go(t.value); };
  A.photo = function () { T.close(); G.photo = true; document.body.classList.add('photo'); var d = document.createElement('div'); d.id = 'photobar'; d.style.cssText = 'position:absolute;left:0;right:0;bottom:30px;text-align:center;z-index:9'; d.innerHTML = '<button class="gold" data-a="shot">촬영 (PNG 저장)</button> <button data-a="pose">포즈 바꾸기</button> <button data-a="photoend">끝내기</button><div class="sm" style="text-shadow:2px 2px 0 #000;margin-top:8px">드래그로 카메라 회전 · 휠/핀치로 거리 조절</div>'; document.getElementById('ui').appendChild(d); };
  A.shot = function () { G.wantShot = true; AUD.sfx('shutter'); ST.bump('photos', 1); }; A.pose = function () { var p = ['idle', 'cast', 'atk', 'glide', 'run']; G.P.anim = p[(p.indexOf(G.P.anim) + 1) % p.length]; G.P.atkPhase = 1; G.poseHold = true; };
